  let json = null;
  try { json = await res.json(); } catch { /* empty body */ }
  return { status: res.status, json };
}

// --- the member's delivery preference ----------------------------------------

// The member's delivery preference, normalized. `push`/`auto` → auto-merge and
// `pr` → review are the permanent legacy aliases (the maintenance-lane tolerance);
// anything else is invalid (null) and fails the run rather than guessing.
export function normalizeDelivery(raw) {
  const v = String(raw ?? '').trim();
  if (v === 'auto-merge' || v === 'auto' || v === 'push') return 'auto-merge';
  if (v === 'review' || v === 'pr') return 'review';
  return null;
}

// The default a repo gets when it never declared one.
export const DEFAULT_DELIVERY = 'auto-merge';

// @deprecated — the `maintenance.delivery` resolution, kept callable for the
// fielded workers that still import it (an `updates/*`-class surface: a member's
// vendored worker is a cycle behind the flows that rewrote its declaration). New
// callers ask `deliveryFor` below, which reads the current key.
//
// `maintenance.delivery` was always EXPLICIT — but a key that is simply absent is
// DRIFT, not an error. A repo adopted before the key existed, or one whose key
// was hand-removed, would otherwise fail its scheduled tasks every night forever
// with nothing that could ever fix it. So: resolve to the default and carry on —
// `materialize: true` tells the one caller that CAN write the repair to do so.
//
// An UNRECOGNIZED value is a different thing entirely: someone wrote an intent
// this code cannot honour, and silently substituting a default would deliver
// the opposite of what they asked for. That still fails the run (delivery: null).
export function resolveDelivery(raw) {
  if (raw == null || String(raw).trim() === '') {
    return { delivery: DEFAULT_DELIVERY, materialize: true };
  }
  return { delivery: normalizeDelivery(raw), materialize: false };
}

// @deprecated with `resolveDelivery` above, and kept callable for the same reason.
export function deliveryFromChecks(text) {
  let parsed = null;
  try { parsed = JSON.parse(text ?? 'null'); } catch { /* unreadable → absent */ }
  return resolveDelivery(parsed?.maintenance?.delivery);
}

// THE MEMBER'S DELIVERY, from its parsed settings. One override, one direction:
// `dailyClaudiniteUpdatesRequirePrReview: true` leaves the PR for a human, and
// anything else — the key absent, which is the normal shape — lands it. That
// asymmetry is the point of #1252: every member wanted the same thing, so the
// setting materialized into every declaration said nothing, and the one repo that
// wants review is the one that should have to say so.
//
// The retired `maintenance.delivery` is read underneath for a member the rename
// record has not reached. Unparsable or absent settings resolve like an absent
// key — auto-merge, not failure: the file's integrity is check_the_world's
// problem, not the delivery step's.
export function deliveryFor(settings) {
  if (settings?.dailyClaudiniteUpdatesRequirePrReview === true) return 'review';
  if (settings?.dailyClaudiniteUpdatesRequirePrReview === undefined
      && normalizeDelivery(settings?.maintenance?.delivery) === 'review') return 'review';
  return DEFAULT_DELIVERY;
}

// The same, from the raw TEXT of a settings file — the shape a caller reading the
// file off a git blob has in hand.
export function deliveryForText(text) {
  let parsed = null;
  try { parsed = JSON.parse(text ?? 'null'); } catch { /* unreadable → absent */ }
  return deliveryFor(parsed);
}

// --- CI dispatch on the delivered PR (#565) -----------------------------------

// edfringe task: refresh-tickets — the in-festival availability refresh.
//
// Refreshes ticket status for today and every remaining festival date, writing
// through the master so every derived file regenerates from one source (#249).
//
// `daily+1h` rather than the plain `daily` anchor: it runs after refresh-shows'
// catalogue top-up, and the two data-committing tasks never share a checkout.
//
// `agent_model: 'none'` — the whole job is deterministic, so there is no agent
// and no dispatch issue: the scheduler runs `code_work` as a subprocess and that
// is the entire task. A non-zero exit converges to one open `needs-human` issue.
//
// Self-contained (imports nothing). `edinburghClock` and `ticketWindow` are
// exported beside the declaration so the gate is unit-tested directly
// (window.test.mjs) rather than only reasoned about.

// The calendar gate: the festival month, read on the Edinburgh clock.
export const FESTIVAL_MONTH = 8;

// Europe/London is UTC+1 for the ENTIRE window, so the conversion is a fixed
// one-hour shift and needs no timezone database. British Summer Time runs from
// the last Sunday in March to the last Sunday in October, so August lies strictly
// inside it with months of margin on both sides — there is no DST boundary
// anywhere near this window, and any instant whose Edinburgh wall clock reads
// August is necessarily under BST. (Instants that shift into any other month are
// rejected by the month test regardless, so the offset cannot matter there.)
// The shift is what decides the month at the instants where UTC and Edinburgh
// disagree about it — the last hours of 31 July and 31 August.
const BST_OFFSET_MS = 60 * 60 * 1000;

// The Edinburgh wall-clock month (1–12) and hour (0–23) at UTC instant `now`.
export function edinburghClock(now) {
  const local = new Date(new Date(now).getTime() + BST_OFFSET_MS);
  return { month: local.getUTCMonth() + 1, hour: local.getUTCHours() };
}

// The precondition's verdict as a pure function of the instant — `{ run, reason }`.
export function ticketWindow(now) {
  const { month, hour } = edinburghClock(now);
  const clock = `${String(hour).padStart(2, '0')}:xx Edinburgh, month ${month}`;
  if (month !== FESTIVAL_MONTH) {
    return { run: false, reason: `outside the festival — ${clock}; ticket status only moves during August` };
  }
  // No hour gate: an hours window on a task with one evaluation per slot could
  // only ever silence it.
  return { run: true, reason: `in-festival — ${clock}; refreshing ticket status` };
}

export default {
  id: 'refresh-tickets',
  frequency: 'daily+1h',           // the slot after refresh-shows'; the precondition decides whether to act
  precondition_signals: [],        // the gate is the calendar, not repo state
  agent_model: 'none',             // pure code; the work is the preprocessing subprocess below
  expected_outcome: 'none',        // it commits refreshed statuses straight to the default branch — no PR
  agent_instructions: 'worker.sh', // vestigial for an agentless task; the real work is the command below
  code_work: 'bash worker.sh',
  code_work_timeout: 900,

  precondition() {
    return ticketWindow(new Date());
  },
};

